import{_ as a,o as t,c as o,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Disable hash template variable and updates","description":"Learn how to disable hash template variable updates and when to use this performance option","frontmatter":{"title":"Disable hash template variable and updates","description":"Learn how to disable hash template variable updates and when to use this performance option"},"headers":[],"relativePath":"en/projects/uix/extras/hash-template-variable-updates.md","filePath":"en/projects/uix/extras/hash-template-variable-updates.md","lastUpdated":1793126673000}'),i={name:"en/projects/uix/extras/hash-template-variable-updates.md"};function r(n,e,l,h,d,p){return t(),o("div",null,[...e[0]||(e[0]=[s('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.2</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/26e54e6d4973231a393933e6479ed1b03cc86cd3" target="_blank" rel="noreferrer">26e54e6</a>, reviewed 22 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="disable-hash-template-variable-and-updates" tabindex="-1">Disable hash template variable and updates <a class="header-anchor" href="#disable-hash-template-variable-and-updates" aria-label="Permalink to &quot;Disable hash template variable and updates&quot;">​</a></h1><p>By default, UIX exposes <code>hash</code> as a template variable and updates templates when the URL hash (<code>#...</code>) changes. UIX provides an option to disable this behavior to avoid hash-driven rebinds and Forge updates.</p><h2 id="setting-via-the-integration-ui" tabindex="-1">Setting via the integration UI <a class="header-anchor" href="#setting-via-the-integration-ui" aria-label="Permalink to &quot;Setting via the integration UI&quot;">​</a></h2><p>The option is <strong>unset by default</strong>. To set the option:</p><ol><li>In Home Assistant, go to <strong>Settings → Devices &amp; Services → UI eXtension → Configure</strong>.</li><li>Select <strong>Performance settings</strong> from the menu.</li><li>Toggle <strong>Disable hash template variable and updates</strong> on.</li><li>Save.</li></ol><p>The setting takes effect immediately across all connected browser sessions — no page reload required.</p><h2 id="behavior-when-set" tabindex="-1">Behavior when set <a class="header-anchor" href="#behavior-when-set" aria-label="Permalink to &quot;Behavior when set&quot;">​</a></h2><p>When this option is set:</p><ul><li>The <code>hash</code> template variable is <strong>not available</strong>.</li><li>Hash-only URL changes do <strong>not</strong> trigger UIX template rebinds.</li><li>Hash-only URL changes do <strong>not</strong> trigger UIX Forge updates.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Any template that references <code>hash</code> without default will error while this option is set because <code>hash</code> variable is unavailable. If you wish to have this option both set and unset you will need to set a default if you use <code>hash</code> variable in templates. e.g. <code>{{ hash | default(&quot;&quot;) }}</code> or is using in more complex templates set a local variable and then use that variable. <code>{% set hashWithDefault = hash | default(&quot;&quot;) %}</code></p></div>',11)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
